package dev.reclaim.app.design.icons

import androidx.annotation.DrawableRes
import androidx.compose.foundation.layout.size
import androidx.compose.material3.Icon
import androidx.compose.material3.LocalContentColor
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.res.painterResource
import androidx.compose.ui.unit.Dp
import androidx.compose.ui.unit.dp
import dev.reclaim.app.R

/**
 * One icon set, one size. Heroicons solid, generated by
 * `tools/heroicons_to_vector.py`; never hand-edited.
 */
object ReclaimIcons {
    val Home = R.drawable.ic_home
    val Apps = R.drawable.ic_squares_2x2
    val Reels = R.drawable.ic_film
    val Web = R.drawable.ic_globe_alt
    val Settings = R.drawable.ic_cog_6_tooth
    val Check = R.drawable.ic_check
    val ChevronRight = R.drawable.ic_chevron_right
    val Back = R.drawable.ic_chevron_left
    val Shield = R.drawable.ic_shield_check
    val ShieldAlert = R.drawable.ic_shield_exclamation
    val Moon = R.drawable.ic_moon
    val Sun = R.drawable.ic_sun
    val Clock = R.drawable.ic_clock
    val Bell = R.drawable.ic_bell
    val Plus = R.drawable.ic_plus
    val Search = R.drawable.ic_magnifying_glass
    val Info = R.drawable.ic_information_circle
    val Refresh = R.drawable.ic_arrow_path
    val More = R.drawable.ic_ellipsis_horizontal
    val Close = R.drawable.ic_x_mark
    val Users = R.drawable.ic_users
    val Banknotes = R.drawable.ic_banknotes
}

@Composable
fun ReclaimIcon(
    @DrawableRes icon: Int,
    contentDescription: String?,
    modifier: Modifier = Modifier,
    tint: Color = LocalContentColor.current,
    size: Dp = 24.dp,
) {
    Icon(
        painter = painterResource(icon),
        contentDescription = contentDescription,
        modifier = modifier.size(size),
        tint = tint,
    )
}
